import { View, Text, Pressable, FlatList, StyleSheet } from "react-native";
import { useReducer } from "react";
import { registerRootComponent } from "expo";

const INIT = [{ id: "1", name: "Чихэвч", qty: 1 }, { id: "2", name: "Цүнх", qty: 1 }];

function reducer(state, action) {
  if (action.type === "inc") {
    return state.map((item) => item.id === action.id ? { ...item, qty: item.qty + 1 } : item);
  }
  return state;
}

function App() {
  const [items, dispatch] = useReducer(reducer, INIT);
  return (
    <FlatList
      style={styles.s}
      data={items}
      keyExtractor={(x) => x.id}
      renderItem={({ item }) => (
        <View testID="row" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
          <Text nativeID={"qty-" + item.id} style={styles.qty}>{item.qty}</Text>
          <Pressable nativeID={"inc-" + item.id} style={styles.b} onPress={() => dispatch({ type: "inc", id: item.id })}><Text style={styles.t}>+</Text></Pressable>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, padding: 16 },
  row: { flexDirection: "row", alignItems: "center", gap: 12, padding: 14, backgroundColor: "#f8fafc", borderRadius: 12, marginBottom: 10 },
  name: { flexGrow: 1, fontSize: 16 }, qty: { fontSize: 18, fontWeight: "bold", minWidth: 24, textAlign: "center" },
  b: { backgroundColor: "#2563eb", width: 40, height: 40, borderRadius: 20, alignItems: "center", justifyContent: "center" }, t: { color: "#fff", fontSize: 20, fontWeight: "bold" },
});

registerRootComponent(App);
